 drawMachine(g,reduceM(M).slice(0,9),232,56,-1);
 nt(g,'#35ffb0',24,166,11,'M halts on 0  \\u21d4  M\\u2032 halts with accumulator 7');
 nt(g,'#9cf',24,192,10,'so a decider for the SEMANTIC property P would decide halting');
