 ne(g,'#ff2fa6',1.8);g.beginPath();g.arc(0,0,R,0,6.2832);g.stroke();ng(g);ne(g,'rgba(120,140,200,0.25)',1);g.beginPath();g.moveTo(-R-10,0);g.lineTo(R+10,0);g.moveTo(0,-R-10);g.lineTo(0,R+10);g.stroke();ng(g);
