 nt(g,'#35ffb0',16,80,12,'det(h_{λ_i−i+j}) = '+d.toFixed(6));nt(g,'#ff2fa6',16,106,12,'Σ over '+ss.cnt+' tableaux = '+ss.sum.toFixed(6));
